#!/usr/bin/env node
/**
 * officeparser - Universal Office Document Parser
 * 
 * A comprehensive Node.js library for parsing Microsoft Office and OpenDocument files
 * into structured Abstract Syntax Trees (AST) with full formatting information.
 * 
 * **Supported Formats:**
 * - Microsoft Office: DOCX, XLSX, PPTX (Office Open XML)
 * - OpenDocument: ODT, ODP, ODS (ODF)
 * - Legacy: RTF (Rich Text Format)
 * - Portable: PDF
 * 
 * **Key Features:**
 * - Unified AST output across all formats
 * - Rich text formatting (bold, italic, colors, fonts, etc.)
 * - Document structure (headings, lists, tables)
 * - Image extraction with optional OCR
 * - Metadata extraction
 * - TypeScript support with full type definitions
 * 
 * **Quick Start:**
 * ```typescript
 * import { OfficeParser } from 'officeparser';
 * 
 * const ast = await OfficeParser.parseOffice('document.docx', {
 *   extractAttachments: true,
 *   ocr: true,
 *   includeRawContent: false
 * });
 * 
 * console.log(ast.toText()); // Plain text output
 * console.log(ast.content);  // Structured content tree
 * console.log(ast.metadata); // Document metadata
 * ```
 * 
 * **Main Exports:**
 * - `OfficeParser` - Main parser class
 * - `OfficeParserConfig` - Configuration interface
 * - `OfficeParserAST` - AST result interface
 * - `OfficeContentNode` - Content tree node interface
 * - All type definitions
 * 
 * @packageDocumentation
 * @module officeparser
 */

import { OfficeParser } from './OfficeParser';
import {
    OfficeParserConfig,
    OfficeParserAST,
    OfficeContentNode,
    OfficeAttachment,
    OfficeMetadata,
    TextFormatting,
    SupportedFileType,
    OfficeContentNodeType,
    OfficeMimeType,
    SlideMetadata,
    SheetMetadata,
    HeadingMetadata,
    ListMetadata,
    CellMetadata,
    ImageMetadata,
    PageMetadata,
    ContentMetadata,
    DocImage,
    Block,
    TextBlock,
    ImageBlock,
    TableBlock,
    ChartBlock,
    ChartData,
    ChartMetadata,
    CoordinateData,
    ParagraphMetadata,
    TextMetadata,
    NoteMetadata,
    CommentBlock,
    InsertionBlock,
    DeletionBlock,
    CommentMetadata,
    TrackedChangeMetadata,
    CommentReply
} from './types';

const parseOffice = OfficeParser.parseOffice;

export {
    OfficeParser,
    parseOffice,
    OfficeParserConfig,
    OfficeParserAST,
    OfficeContentNode,
    OfficeAttachment,
    OfficeMetadata,
    TextFormatting,
    SupportedFileType,
    OfficeContentNodeType,
    OfficeMimeType,
    SlideMetadata,
    SheetMetadata,
    HeadingMetadata,
    ListMetadata,
    CellMetadata,
    ImageMetadata,
    PageMetadata,
    ContentMetadata,
    DocImage,
    Block,
    TextBlock,
    ImageBlock,
    TableBlock,
    ChartBlock,
    ChartData,
    ChartMetadata,
    CoordinateData,
    ParagraphMetadata,
    TextMetadata,
    NoteMetadata,
    CommentBlock,
    InsertionBlock,
    DeletionBlock,
    CommentMetadata,
    TrackedChangeMetadata,
    CommentReply
};



// Default export for backward compatibility
export default OfficeParser;

// CLI handling - allows running as: node index.js file.docx
if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
    const args = process.argv.slice(2);
    let fileArg: string | undefined;
    let toText = false;
    const configArgs: string[] = [];

    function isConfigOption(arg: string) {
        return arg.startsWith('--') && arg.includes('=');
    }

    args.forEach(arg => {
        if (isConfigOption(arg)) {
            configArgs.push(arg);
        } else if (!fileArg) {
            fileArg = arg;
        }
    });

    if (fileArg) {
        const config: OfficeParserConfig = {};
        configArgs.forEach(arg => {
            const [key, value] = arg.split('=');
            const cleanKey = key.replace('--', '');
            if (cleanKey === 'toText') {
                if (value.toLowerCase() === 'true') toText = true;
                else if (value.toLowerCase() === 'false') toText = false;
                else console.log(`Invalid value for toText: ${value}`);
            }
            // @ts-ignore
            else if (value.toLowerCase() === 'true') config[cleanKey] = true;
            // @ts-ignore
            else if (value.toLowerCase() === 'false') config[cleanKey] = false;
            // @ts-ignore
            else config[cleanKey] = value;
        });

        OfficeParser.parseOffice(fileArg, config)
            .then((ast: OfficeParserAST) => {
                if (toText) console.log(ast.toText());
                else console.log(JSON.stringify(ast, null, 2));
            })
            .catch(console.error);
    } else {
        console.log("Usage: node officeparser [file] [--option=value]");
    }
}
